# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSTANBUL\'UN FETHİ (29 MAYIS 1453): NEDENLERİ VE HAZIRLIKLAR</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. İstanbul\'un Fethinin Nedenleri</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Coğrafi ve Siyasi: Osmanlı\'nın Anadolu ve Rumeli</text>\n  <text x="52" y="114" font-size="11" fill="#334155">toprakları arasındaki bütünlüğü sağlamak.</text>\n  <text x="44" y="136" font-size="11" fill="#334155">• Güvenlik: Bizans\'ın şehzadeleri ve Haçlıları</text>\n  <text x="52" y="152" font-size="11" fill="#334155">Osmanlı\'ya karşı kışkırtmasını önlemek.</text>\n  <text x="44" y="174" font-size="11" fill="#334155">• Ekonomik: Karadeniz-Akdeniz suyoluna ve İpek</text>\n  <text x="52" y="190" font-size="11" fill="#334155">Yolu ticaret geçişlerine hâkim olmak.</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Manevi Motivasyon: Hz. Peygamber\'in Fetih Hadisi</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. II. Mehmed\'in (Fatih) Fetih Hazırlıkları</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Boğazkesen (Rumeli) Hisarı\'nın inşa edilmesi</text>\n  <text x="386" y="114" font-size="11" fill="#475569">(Anadolu Hisarı\'nın karşısına, Boğaz kontrolü için).</text>\n  <text x="378" y="136" font-size="11" fill="#334155">• Şahi adı verilen dev topların döktürülmesi ve</text>\n  <text x="386" y="152" font-size="11" fill="#475569">tekerlekli kuşatma kulelerinin yapılması.</text>\n  <text x="378" y="174" font-size="11" fill="#334155">• 400 parçalık güçlü bir donanma hazırlanması ve</text>\n  <text x="386" y="190" font-size="11" fill="#475569">72 geminin karadan Haliç\'e indirilmesi!</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Bilim · Teknoloji · Askerî Deha</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSTANBUL\'UN FETHİNİN TÜRK VE DÜNYA TARİHİ AÇISINDAN SONUÇLARI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Türk ve İslam Tarihi Açısından Sonuçları</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">• Osmanlı Devleti Kuruluş\'tan Yükselme (Cihan</text>\n  <text x="54" y="116" font-size="11" fill="#334155">Devleti / İmparatorluk) dönemine geçti.</text>\n  <text x="44" y="140" font-size="11.5" fill="#334155">• İstanbul Osmanlı Devleti\'nin yeni başkenti oldu;</text>\n  <text x="54" y="156" font-size="11" fill="#334155">Anadolu ve Rumeli toprak bütünlüğü sağlandı.</text>\n  <text x="44" y="180" font-size="11.5" fill="#334155">• Karadeniz-Akdeniz su yolu ve İpek Yolu\'nun</text>\n  <text x="54" y="196" font-size="11" fill="#334155">Avrupa\'ya açılan kolu Osmanlı denetimine girdi.</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">II. Mehmed \'Fatih\' Unvanını Aldı · İstimalet Uygulandı</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Dünya Tarihi Açısından Sonuçları</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• Bin yıllık Bizans (Doğu Roma) İmparatorluğu</text>\n  <text x="388" y="116" font-size="11" fill="#334155">yıkıldı; Orta Çağ kapandı, Yeni Çağ başladı.</text>\n  <text x="378" y="140" font-size="11.5" fill="#334155">• Şahi toplarının surları yıkmasıyla Avrupa\'da</text>\n  <text x="388" y="156" font-size="11" fill="#334155">derebeylik (feodalite) rejimi zayıfladı.</text>\n  <text x="378" y="180" font-size="11.5" fill="#334155">• Ticaret yollarının Osmanlı\'ya geçmesi Avrupalıları</text>\n  <text x="388" y="196" font-size="11" fill="#334155">Coğrafi Keşiflere yöneltti; İtalya\'da Rönesans başladı.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Orta Çağ Bitti → Yeni Çağ Başladı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CİHAN DEVLETİ (YÜKSELME) DÖNEMİ SİYASİ VE DENİZCİLİK GELİŞMELERİ</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Fatih ve II. Bayezid Dönemi</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Anadolu birliği: Amasra, Sinop,</text>\n  <text x="40" y="114" font-size="11" fill="#334155">  Trabzon (1461) ve Otlukbeli (1473).</text>\n  <text x="40" y="136" font-size="11" fill="#334155">• Kırım\'ın Fethi (1475): Karadeniz</text>\n  <text x="40" y="152" font-size="11" fill="#334155">  \'Türk Gölü\' hâline geldi.</text>\n  <text x="40" y="174" font-size="11" fill="#334155">• Balkanlar: Sırbistan, Mora,</text>\n  <text x="40" y="190" font-size="11" fill="#334155">  Eflak, Boğdan, Bosna-Hersek.</text>\n  <text x="130" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Sahn-ı Seman Medreseleri</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Yavuz Sultan Selim (1512-1520)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Çaldıran Savaşı (1514): Doğu</text>\n  <text x="260" y="114" font-size="11" fill="#334155">  Anadolu güvenliği sağlandı.</text>\n  <text x="260" y="136" font-size="11" fill="#334155">• Turnadağ (1515): Dulkadiroğulları</text>\n  <text x="260" y="152" font-size="11" fill="#334155">  alındı, Anadolu Türk birliği kesinleşti.</text>\n  <text x="260" y="174" font-size="11" fill="#334155">• Mercidabık (1516) ve Ridaniye (1517):</text>\n  <text x="260" y="190" font-size="11" fill="#334155">  Mısır Seferi, Halifelik ve Baharat Yolu.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Hazine Ağzına Kadar Doldu</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kanuni Sultan Süleyman (1520-1566)</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Belgrad (1521), Rodos (1522) ve</text>\n  <text x="480" y="114" font-size="11" fill="#334155">  Mohaç Meydan Muharebesi (1526).</text>\n  <text x="480" y="136" font-size="11" fill="#334155">• Preveze Deniz Zaferi (1538):</text>\n  <text x="480" y="152" font-size="11" fill="#334155">  Barbaros Hayreddin Paşa ile</text>\n  <text x="480" y="168" font-size="11" fill="#334155">  Akdeniz\'de Osmanlı üstünlüğü.</text>\n  <text x="480" y="190" font-size="11" fill="#334155">• Kıbrıs\'ın Fethi (1571 - II. Selim).</text>\n  <text x="570" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Üç Kıtada Adalet ve Hâkimiyet</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
